from typing import List

def median(l: List[float]):
    """Return median of elements in the given list."""
    n = len(l)
    if n == 0:
        raise ValueError("The list must not be empty.")

    # If the list has an odd number of elements, the median is the middle one.
    # If it has an even number of elements, the median is the average of the two middle elements.
    if n % 2 != 0:
        return float(l[n // 2])
    else:
        return (l[n // 2 - 1] + l[n // 2]) / 2.0
