def largest_prime_factor(n: int):
    prime_factors = []
    # Check for factor 2
    while n % 2 == 0:
        prime_factors.append(2)
        n //= 2
    # Check for odd factors
    for i in range(3, int(n**0.5) + 1, 2):
        while n % i == 0:
            prime_factors.append(i)
            n //= i
    # If n is a prime number greater than 2
    if n > 2:
        prime_factors.append(n)
    return max(prime_factors) if prime_factors else 2 # Optional: Return the largest prime factor if the list of prime factors is empty (default)


