from collections import Counter

def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    if not test:
        return {}

    # Count occurrences of each letter
    letter_counts = Counter(test)

    # Find the letter with the highest count
    most_common_letter = most_common(letter_counts)

    # Return the frequency count of the letter
    return most_common_letter

def most_common(count):
    """Return the most common element based on the given count array.
    Args:
    count: A list of integers representing the occurrences of each character.

    Returns:
    The most common element in the given count array as a tuple.
    """

    # Sort the keys based on the values in descending order
    sorted_keys = sorted(count.keys(), key=lambda k: -k)

    # Return the first element as it will always be the most frequent
    return (sorted_keys[0], count[sorted_keys[0]])

